command:
set -eu
cd /srv/legacy2/mail-filter-routing
sha256sum samples/*.eml > /tmp/mail-filter-routing-samples.before
cat > /tmp/deliver.new <<'ANTRIEB_DELIVER_EOF'
#!/bin/sh
set -eu

base=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
maildir=$base/Maildir

umask 077
for department in accounts support general; do
    mkdir -p "$maildir/$department/cur" \
             "$maildir/$department/new" \
             "$maildir/$department/tmp"
done
mkdir -p "$maildir/tmp"

staging=$(mktemp "$maildir/tmp/.deliver.XXXXXX")
trap 'if [ -n "$staging" ]; then rm -f "$staging"; fi' 0 1 2 3 15
cat > "$staging"

department=$(awk '
{
    line = $0
    sub(/\r$/, "", line)
    if (line ~ /^[[:space:]]*$/) {
        exit
    }
    colon = index(line, ":")
    if (colon == 0) {
        next
    }
    name = tolower(substr(line, 1, colon - 1))
    gsub(/^[[:space:]]+|[[:space:]]+$/, "", name)
    if (name != "x-department") {
        next
    }
    value = tolower(substr(line, colon + 1))
    gsub(/^[[:space:]]+|[[:space:]]+$/, "", value)
    if (value == "accounts") {
        accounts = 1
    } else if (value == "support") {
        support = 1
    }
}
END {
    if (accounts) {
        print "accounts"
    } else if (support) {
        print "support"
    } else {
        print "general"
    }
}
' "$staging")

unique=${staging##*/}
unique=${unique#.deliver.}
destination=$maildir/$department/new/$(date +%s).$$.$unique
mv "$staging" "$destination"
staging=
trap - 0 1 2 3 15
ANTRIEB_DELIVER_EOF
sh -n /tmp/deliver.new
install -o root -g root -m 0755 /tmp/deliver.new bin/deliver
printf '%s\n' 'installed:'
sed -n '1,200p' bin/deliver
printf '%s\n' 'sample hashes before:'
cat /tmp/mail-filter-routing-samples.before

